-- Read-only annual and monthly comparisons of daily extrema against raw production archive.
-- Day assignment: DATE(FROM_UNIXTIME(dateTime-1)); verified DB session timezone Europe/Prague.
-- Annual range through complete local day 2026-11-12; 2021 is diagnostic only.
WITH raw AS (SELECT DATE(FROM_UNIXTIME(dateTime-1)) local_date,MIN(outHumidity) hmin,MAX(outHumidity) hmax,MIN(rain) rmin,MAX(rain) rmax,MIN(windSpeed) wsmin,MAX(windSpeed) wsmax,MIN(windGust) wgmin,MAX(windGust) wgmax FROM `pocasi-loucka.eu`.archive WHERE dateTime>1238194800 AND dateTime<=1794524400 GROUP BY DATE(FROM_UNIXTIME(dateTime-1))), d AS (SELECT 'outHumidity' v,dateTime,`min` dmin,`max` dmax FROM `pocasi-loucka.eu`.archive_day_outHumidity WHERE dateTime<1794524400 UNION ALL SELECT 'rain',dateTime,`min`,`max` FROM `pocasi-loucka.eu`.archive_day_rain WHERE dateTime<1794524400 UNION ALL SELECT 'windSpeed',dateTime,`min`,`max` FROM `pocasi-loucka.eu`.archive_day_windSpeed WHERE dateTime<1794524400 UNION ALL SELECT 'windGust',dateTime,`min`,`max` FROM `pocasi-loucka.eu`.archive_day_windGust WHERE dateTime<1794524400), x AS (SELECT YEAR(FROM_UNIXTIME(d.dateTime)) local_year,d.v,d.dmin,d.dmax,CASE d.v WHEN 'outHumidity' THEN r.hmin WHEN 'rain' THEN r.rmin WHEN 'windSpeed' THEN r.wsmin ELSE r.wgmin END rmin,CASE d.v WHEN 'outHumidity' THEN r.hmax WHEN 'rain' THEN r.rmax WHEN 'windSpeed' THEN r.wsmax ELSE r.wgmax END rmax FROM d LEFT JOIN raw r ON r.local_date=DATE(FROM_UNIXTIME(d.dateTime))) SELECT local_year,v variable,COUNT(*) summary_days,SUM(rmin IS NULL AND rmax IS NULL) raw_extrema_null_days,SUM((dmin IS NULL)<>(rmin IS NULL)) min_null_mismatch,SUM(dmin IS NOT NULL AND rmin IS NOT NULL AND NOT(dmin<=>rmin)) min_numeric_mismatch,SUM(ABS(dmin-rmin)>0.1) min_gt_0_1,SUM((dmax IS NULL)<>(rmax IS NULL)) max_null_mismatch,SUM(dmax IS NOT NULL AND rmax IS NOT NULL AND NOT(dmax<=>rmax)) max_numeric_mismatch,SUM(ABS(dmax-rmax)>0.1) max_gt_0_1,MAX(GREATEST(ABS(dmin-rmin),ABS(dmax-rmax))) max_abs_extreme_diff FROM x GROUP BY local_year,v ORDER BY local_year,v;

-- Monthly 2026 detail
WITH raw AS (SELECT DATE(FROM_UNIXTIME(dateTime-1)) local_date,MIN(outHumidity) hmin,MAX(outHumidity) hmax,MIN(rain) rmin,MAX(rain) rmax,MIN(windSpeed) wsmin,MAX(windSpeed) wsmax,MIN(windGust) wgmin,MAX(windGust) wgmax FROM `pocasi-loucka.eu`.archive WHERE dateTime>1767222000 AND dateTime<=1794524400 GROUP BY DATE(FROM_UNIXTIME(dateTime-1))), d AS (SELECT 'outHumidity' v,dateTime,`min` dmin,`max` dmax FROM `pocasi-loucka.eu`.archive_day_outHumidity WHERE dateTime>=1767222000 AND dateTime<1794524400 UNION ALL SELECT 'rain',dateTime,`min`,`max` FROM `pocasi-loucka.eu`.archive_day_rain WHERE dateTime>=1767222000 AND dateTime<1794524400 UNION ALL SELECT 'windSpeed',dateTime,`min`,`max` FROM `pocasi-loucka.eu`.archive_day_windSpeed WHERE dateTime>=1767222000 AND dateTime<1794524400 UNION ALL SELECT 'windGust',dateTime,`min`,`max` FROM `pocasi-loucka.eu`.archive_day_windGust WHERE dateTime>=1767222000 AND dateTime<1794524400), x AS (SELECT DATE_FORMAT(FROM_UNIXTIME(d.dateTime),'%Y-%m') local_month,d.v,d.dmin,d.dmax,CASE d.v WHEN 'outHumidity' THEN r.hmin WHEN 'rain' THEN r.rmin WHEN 'windSpeed' THEN r.wsmin ELSE r.wgmin END rmin,CASE d.v WHEN 'outHumidity' THEN r.hmax WHEN 'rain' THEN r.rmax WHEN 'windSpeed' THEN r.wsmax ELSE r.wgmax END rmax FROM d JOIN raw r ON r.local_date=DATE(FROM_UNIXTIME(d.dateTime))) SELECT local_month,v variable,COUNT(*) summary_days,SUM((dmin IS NULL)<>(rmin IS NULL)) min_null_mismatch,SUM(dmin IS NOT NULL AND rmin IS NOT NULL AND NOT(dmin<=>rmin)) min_numeric_mismatch,SUM(ABS(dmin-rmin)>0.1) min_gt_0_1,SUM((dmax IS NULL)<>(rmax IS NULL)) max_null_mismatch,SUM(dmax IS NOT NULL AND rmax IS NOT NULL AND NOT(dmax<=>rmax)) max_numeric_mismatch,SUM(ABS(dmax-rmax)>0.1) max_gt_0_1,MAX(ABS(dmin-rmin)) max_min_diff,MAX(ABS(dmax-rmax)) max_max_diff FROM x GROUP BY local_month,v ORDER BY local_month,v;


-- 2026 exact archive-row presence for stored extrema timestamps (not a validity test).
SELECT 'outHumidity' variable,YEAR(FROM_UNIXTIME(d.dateTime)) local_year,COUNT(*) days,SUM(m.dateTime IS NULL) mintime_absent,SUM(mx.dateTime IS NULL) maxtime_absent FROM `pocasi-loucka.eu`.archive_day_outHumidity d LEFT JOIN `pocasi-loucka.eu`.archive m ON m.dateTime=d.mintime LEFT JOIN `pocasi-loucka.eu`.archive mx ON mx.dateTime=d.maxtime WHERE d.dateTime>=1767222000 AND d.dateTime<1794524400 GROUP BY YEAR(FROM_UNIXTIME(d.dateTime)) UNION ALL SELECT 'rain',YEAR(FROM_UNIXTIME(d.dateTime)),COUNT(*),SUM(m.dateTime IS NULL),SUM(mx.dateTime IS NULL) FROM `pocasi-loucka.eu`.archive_day_rain d LEFT JOIN `pocasi-loucka.eu`.archive m ON m.dateTime=d.mintime LEFT JOIN `pocasi-loucka.eu`.archive mx ON mx.dateTime=d.maxtime WHERE d.dateTime>=1767222000 AND d.dateTime<1794524400 GROUP BY YEAR(FROM_UNIXTIME(d.dateTime)) UNION ALL SELECT 'windSpeed',YEAR(FROM_UNIXTIME(d.dateTime)),COUNT(*),SUM(m.dateTime IS NULL),SUM(mx.dateTime IS NULL) FROM `pocasi-loucka.eu`.archive_day_windSpeed d LEFT JOIN `pocasi-loucka.eu`.archive m ON m.dateTime=d.mintime LEFT JOIN `pocasi-loucka.eu`.archive mx ON mx.dateTime=d.maxtime WHERE d.dateTime>=1767222000 AND d.dateTime<1794524400 GROUP BY YEAR(FROM_UNIXTIME(d.dateTime)) UNION ALL SELECT 'windGust',YEAR(FROM_UNIXTIME(d.dateTime)),COUNT(*),SUM(m.dateTime IS NULL),SUM(mx.dateTime IS NULL) FROM `pocasi-loucka.eu`.archive_day_windGust d LEFT JOIN `pocasi-loucka.eu`.archive m ON m.dateTime=d.mintime LEFT JOIN `pocasi-loucka.eu`.archive mx ON mx.dateTime=d.maxtime WHERE d.dateTime>=1767222000 AND d.dateTime<1794524400 GROUP BY YEAR(FROM_UNIXTIME(d.dateTime)) ORDER BY variable;
